// Checks and prepares a site visit booking. Nothing is saved unless every check passes.
// Office hours: Monday to Saturday, 9:30 AM to 6:30 PM (India time).
const q = $('When Called by Agent').first().json;
const visits = $('Read Site Visits').all().map(i => i.json).filter(v => v.Visit_ID);
const s = v => (v === undefined || v === null) ? '' : String(v).trim();
const problems = [];
const name = s(q.name);
let phone = s(q.phone).replace(/[^0-9]/g, '');
if (phone.length === 10) phone = '91' + phone;
const property = s(q.property);
if (name.length < 2) problems.push("the visitor's name is missing");
if (phone.length < 11 || phone.length > 13) problems.push('a valid phone number (10 digits) is missing');
if (!property) problems.push('which property to visit is missing');
const dm = s(q.date).match(/^(\d{4})-(\d{2})-(\d{2})$/);
const tm = s(q.time).toUpperCase().replace(/\s+/g, '').match(/^(\d{1,2})(?::(\d{2}))?(AM|PM)?$/);
let when = null, hh = 0, mm = 0;
if (!dm) problems.push('the visit date is missing (yyyy-MM-dd)');
if (!tm) problems.push('the visit time is missing (e.g. 11:00 AM)');
if (dm && tm) {
  hh = +tm[1]; mm = +(tm[2] || 0);
  if (tm[3] === 'PM' && hh < 12) hh += 12;
  if (tm[3] === 'AM' && hh === 12) hh = 0;
  when = Date.UTC(+dm[1], +dm[2] - 1, +dm[3], hh, mm) - 5.5 * 3600000; // IST -> UTC
  const dow = new Date(Date.UTC(+dm[1], +dm[2] - 1, +dm[3])).getUTCDay();
  const mins = hh * 60 + mm;
  if (when < Date.now() + 60 * 60000) problems.push('the visit must be at least 1 hour from now');
  if (dow === 0) problems.push('site visits are not available on Sundays');
  if (mins < 9 * 60 + 30 || mins > 18 * 60 + 30) problems.push('site visits are between 9:30 AM and 6:30 PM');
}
const pad = n => String(n).padStart(2, '0');
const date = dm ? dm[0] : '';
const time = pad(hh) + ':' + pad(mm);
if (!problems.length) {
  const nt = t => { const m = s(t).match(/(\d{1,2}):(\d{2})/); return m ? pad(+m[1]) + ':' + m[2] : s(t); };
  const clash = visits.some(v => s(v.Status).toLowerCase() !== 'cancelled' && s(v.Property).toLowerCase() === property.toLowerCase() && s(v.Visit_Date).slice(0, 10) === date && nt(v.Visit_Time) === time);
  if (clash) problems.push('that time slot is already taken for this property, please choose another time');
}
if (problems.length) return [{ json: { ok: false, reason: problems.join('; ') } }];
const local = new Date(Date.now() + 5.5 * 3600000);
const stamp = String(local.getUTCFullYear()).slice(2) + pad(local.getUTCMonth() + 1) + pad(local.getUTCDate()) + '-' + pad(local.getUTCHours()) + pad(local.getUTCMinutes());
const used = new Set(visits.map(v => s(v.Visit_ID)));
let id;
do { id = 'SV-' + stamp + '-' + Math.random().toString(36).slice(2, 5).toUpperCase(); } while (used.has(id));
const h12 = ((hh + 11) % 12 + 1) + ':' + pad(mm) + (hh < 12 ? ' AM' : ' PM');
return [{ json: {
  ok: true,
  Visit_ID: id,
  Booked_At: local.toISOString().slice(0, 16).replace('T', ' '),
  Customer_Name: name,
  Customer_Phone: phone,
  Property: property,
  Visit_Date: date,
  Visit_Time: time,
  Visit_Time_Label: h12,
  Notes: s(q.notes),
  Channel: s(q.channel) || 'whatsapp',
  Status: 'Scheduled',
} }];

// Only the sheet columns.
const v = $('Check Visit').first().json;
return [{ json: { Visit_ID: v.Visit_ID, Booked_At: v.Booked_At, Customer_Name: v.Customer_Name, Customer_Phone: v.Customer_Phone, Property: v.Property, Visit_Date: v.Visit_Date, Visit_Time: v.Visit_Time, Notes: v.Notes, Channel: v.Channel, Status: v.Status } }];

